const codeLines=[['enrolled = True','Create the variable enrolled and assign the Boolean value True. The single equals sign stores a value. It does not ask whether two values are equal.'],['completed_safety = False','Store a verified False input for this example. The underscore makes a readable single variable name. Missing information would need its own explicit handling.'],['suspended = False','Store an explicit record that the student is not suspended. Avoid assuming this value merely because no record was found.'],['may_enter = enrolled and completed_safety and not suspended','Evaluate the condition and store its result. and requires all conditions to hold. not suspended reverses the Boolean suspension value.'],['print(may_enter)','Call the print function with the variable’s current value. Parentheses enclose the argument. No quotes means inspect the variable, rather than display its name as text.'],['if may_enter:','If the stored condition is true, execute the indented block. The colon starts the block. The expression was evaluated earlier when may_enter was assigned.'],['    print("Lab access granted")','Four leading spaces place this instruction inside the if block. Quotes make the message a text string. It executes only when the if condition holds.'],['else:','Choose the alternative block when the if condition is false. else aligns with its if. The colon again begins the indented block.'],['    print("Check requirements")','This indented message belongs to else. The program prints it when at least one required Boolean condition fails.']];
// The teaching interpreter parses a small Python subset. It never evaluates JavaScript source.
function runTeachingCode(source){
  const env=Object.create(null),output=[];
  function tokenize(s,n){const tokens=[];let pos=0;while(pos<s.length){const rest=s.slice(pos),m=rest.match(/^(\s+|"[^"\\]*"|'[^'\\]*'|[A-Za-z_]\w*|[()])/);if(!m)throw Error('Line '+n+': unsupported expression. Use Boolean names, and/or/not, parentheses, or simple quoted text.');pos+=m[0].length;if(!/^\s+$/.test(m[0]))tokens.push(m[0]);}return tokens;}
  function expression(s,n){const ts=tokenize(s,n);let i=0;const at=()=>ts[i];function atom(){const t=ts[i++];if(t==='('){const node=or();if(ts[i++]!==')')throw Error('Line '+n+': missing closing parenthesis.');return node;}if(t==='True'||t==='False')return {value:t==='True'};if(t&&/^['"]/.test(t))return {value:t.slice(1,-1)};if(t&&/^[A-Za-z_]\w*$/.test(t)&&!['and','or','not'].includes(t))return {name:t};throw Error('Line '+n+': expected a Boolean value or variable name.');}function neg(){if(at()==='not'){i++;return {op:'not',right:neg()};}return atom();}function and(){let node=neg();while(at()==='and'){i++;node={op:'and',left:node,right:neg()};}return node;}function or(){let node=and();while(at()==='or'){i++;node={op:'or',left:node,right:and()};}return node;}const ast=or();if(i!==ts.length)throw Error('Line '+n+': unexpected token '+ts[i]+'.');function bool(v){if(typeof v!=='boolean')throw Error('Line '+n+': this teaching subset requires Boolean conditions (True or False).');return v;}function evaluate(a){if(Object.hasOwn(a,'value'))return a.value;if(a.name){if(!Object.hasOwn(env,a.name))throw Error('Line '+n+': NameError — '+a.name+' has not been assigned.');return env[a.name];}if(a.op==='not')return !bool(evaluate(a.right));const l=bool(evaluate(a.left));return a.op==='and'?(l?bool(evaluate(a.right)):false):(l?true:bool(evaluate(a.right)));}return evaluate(ast);}
  try{if(source.length>12000)throw Error('Keep this exercise under 12,000 characters.');const lines=source.replace(/\r/g,'').split('\n').map((raw,i)=>{if(raw.includes('\t'))throw Error('Line '+(i+1)+': use spaces rather than tabs in this teaching subset.');const indent=raw.match(/^ */)[0].length;return {text:raw.trim(),indent,n:i+1};}).filter(l=>l.text&&!l.text.startsWith('#'));if(lines.length>100)throw Error('Keep this exercise under 100 instructions.');let cursor=0;function block(indent,execute){let count=0;while(cursor<lines.length){const l=lines[cursor];if(l.indent<indent||l.text==='else:')break;if(l.indent>indent)throw Error('Line '+l.n+': unexpected indentation.');cursor++;count++;const ifMatch=l.text.match(/^if\s+(.+):$/);if(ifMatch){const value=execute?expression(ifMatch[1],l.n):false;if(execute&&typeof value!=='boolean')throw Error('Line '+l.n+': if requires a Boolean value in this teaching subset.');if(!lines[cursor]||lines[cursor].indent!==indent+4)throw Error('Line '+l.n+': indent the if block by four spaces.');block(indent+4,execute&&value);if(lines[cursor]?.text==='else:'&&lines[cursor].indent===indent){const e=lines[cursor++];if(!lines[cursor]||lines[cursor].indent!==indent+4)throw Error('Line '+e.n+': indent the else block by four spaces.');block(indent+4,execute&&!value);}continue;}const assignment=l.text.match(/^([A-Za-z_]\w*)\s*=\s*(?!=)(.+)$/),print=l.text.match(/^print\((.*)\)$/);if(assignment){if(['True','False','and','or','not','if','else','print'].includes(assignment[1]))throw Error('Line '+l.n+': choose a variable name that is not a reserved teaching word.');if(execute)env[assignment[1]]=expression(assignment[2],l.n);}else if(print){if(execute){const v=expression(print[1],l.n);output.push(typeof v==='boolean'?truth(v):String(v));}}else throw Error('Line '+l.n+': unsupported instruction. Use assignment, if/else, or print.');}return count;}block(0,true);if(cursor<lines.length)throw Error('Line '+lines[cursor].n+': else needs a matching if at the same indentation.');return output.length?output.join('\n'):'No output. Add print() to inspect a value.';}catch(e){return (output.length?output.join('\n')+'\n':'')+e.message;}
}
const glossary=[['Knowledge representation','A format that makes relevant facts, relationships, rules, or beliefs usable by a system.'],['Knowledge base','A collection of represented knowledge that a system can use.'],['Declarative knowledge','Facts or claims about a situation.'],['Procedural knowledge','Instructions or methods for performing a task.'],['Heuristic','A useful rule of thumb or estimate that can have exceptions.'],['Meta-knowledge','Knowledge about knowledge, such as its source or how to apply it.'],['Semantic network','Entities or concepts connected by meaningful labelled relationships.'],['Frame','Named attributes grouped around an entity or situation.'],['Ontology','A shared definition of concepts, relations, and constraints in a domain.'],['Provenance','Where a claim came from and its relevant context.'],['Closed-world assumption','An explicit modelling assumption that unrecorded facts are false.'],['Inference','Deriving a conclusion from facts or premises using a rule.'],['Deduction','Reasoning that preserves truth under true premises and valid inference rules.'],['Induction','Generalising or predicting from observations, with uncertainty.'],['Abduction','Inferring a plausible explanation for observations.'],['Default reasoning','Using assumptions that may be withdrawn when exceptions appear.'],['Proposition','A complete statement treated as true or false in classical propositional logic.'],['Predicate','A property or relation whose truth depends on its arguments.'],['Domain','The set of entities over which a variable or quantifier ranges.'],['Universal quantifier ∀','A property holds for every member of the stated domain.'],['Existential quantifier ∃','At least one member of the stated domain has the property.'],['Boolean','A value with one of two possibilities: True or False.'],['Assignment =','Store a value under a variable name in Python.'],['Equality ==','Compare values for equality in Python.'],['Indentation','Leading spaces that define which Python statements belong in a block.'],['Confusion matrix','Counts of actual classes compared with predicted classes.'],['True positive','A correctly predicted positive, here spam caught.'],['False positive','A wrongly predicted positive, here a normal message flagged.'],['False negative','An actual positive missed by the prediction, here spam kept.'],['True negative','A correctly predicted negative, here a normal message kept.'],['Accuracy','(TP+TN)/all examples: proportion of correct predictions.'],['Precision','TP/(TP+FP): proportion of flagged examples that are truly positive.'],['Recall','TP/(TP+FN): proportion of actual positives that are caught.'],['F1 score','2TP/(2TP+FP+FN), equivalent to the harmonic mean of precision and recall when defined.'],['Threshold','A decision boundary applied to a score to select a predicted class.'],['Baseline','A simple reference method used for comparison.'],['Class imbalance','Unequal numbers of examples in different classes.'],['Validation set','Separate examples used to tune choices such as a threshold.'],['Test set','Held-out examples used for final evaluation after choices are fixed.'],['MAE','Mean absolute error: average magnitude of numeric prediction errors in target units.'],['RMSE','Root mean squared error: square errors, average, and take a square root. Large errors count more.'],['R²','1 minus squared-error ratio against a mean baseline. Can be negative and depends on the evaluation set.'],['ROC-AUC','Summary of a score’s positive/negative ranking across thresholds. Read alongside task and class balance.'],['Generative AI','Models that produce content such as text, images, or audio from learned patterns and context.'],['Token','A unit processed by a model, often a piece of text rather than a whole word.'],['Hallucination / confabulation','A generated claim that is false or unsupported, sometimes expressed confidently.'],['RAG','Retrieval-augmented generation: retrieve relevant source material to help compose an answer.'],['Grounding','Connecting an answer’s claims to relevant supporting evidence.'],['Multimodal','Working with more than one form of input or output, such as text and images.'],['Latency','Time taken to return a result.']];
const stage=document.getElementById('stage');let lastFocus=null,seconds=7200,timerRunning=false,timerInterval=null;
function go(i){state.slide=Math.max(0,Math.min(slides.length-1,Number(i)||0));save();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){const i=state.slide,s=slides[i],sec=sectionFor(i);document.title='Session 04 · '+s.title;stage.innerHTML='<article class="slide session04"><div class="slide-head"><div class="section-label"><span class="rule"></span><span class="eyebrow">'+esc(s.kicker)+'</span></div>'+(i===0?'':'<h2>'+esc(s.title)+'</h2>')+'</div>'+s.html()+'</article>';document.getElementById('pageLabel').textContent=(i+1)+' / '+slides.length+' · '+sec.name;document.getElementById('prevBtn').disabled=i===0;document.getElementById('nextBtn').disabled=i===slides.length-1;document.getElementById('progressFill').style.width=((i+1)/slides.length*100)+'%';document.getElementById('progress').setAttribute('aria-valuenow',i+1);document.getElementById('progress').setAttribute('aria-valuemax',slides.length);if(i===11)updateRules();if(i===19)updateLogic();if(i===20)updatePredicates();if(i===28)updateMetrics();if(i===35&&state.genOutput)showGenerated();}
function showGenerated(){const a=groundedAnswer(state.genQuestion,state.grounded);state.genOutput=a.text;save();document.getElementById('genAnswer').textContent=a.text;document.getElementById('genAnswer').classList.toggle('unsupported',!a.supported);document.getElementById('genWhy').textContent=a.why;}
function downloadWork(){const labels={knowledgeUpdate:'Changed evidence and dependent conclusion',codePrediction:'Predicted code outputs',codeMeaning:'Meaning of indentation',metricsMath:'Metric calculations',metricChoice:'Threshold trade-off',ownKnowledge:'Own assistant facts, representation, and rules',ownUnknown:'Unknown fact and follow-up question',exitWhy:'Why representation and evaluation matter'};const pieces=['FOUNDATIONS OF AI · SESSION 04','Student worksheet · '+new Date().toLocaleDateString(),''];for(const [k,label] of Object.entries(labels))pieces.push(label+'\n'+(state.worksheet[k]||'[Not answered]')+'\n');pieces.push('MY RULE CODE\n'+state.code,'LAST TEACHING-INTERPRETER OUTPUT\n'+(state.codeOutput||'[Not run]'),'KNOWLEDGE LAB FACTS\n'+JSON.stringify(state.facts),'CURRENT RULE CONCLUSIONS\n'+knowledgeTrace(state.facts).map(t=>t.name+': '+truth(t.value)).join('\n'),'METRICS LAB\nMode: '+(state.baseline?'always normal':'threshold '+state.threshold/100)+'\n'+JSON.stringify(metricsAt(state.threshold,state.baseline)),'SCRIPTED EVIDENCE CHECK\n'+(state.genOutput||'[Not run]'),'QUICK CHECKS');for(const [id,q] of Object.entries(quizData))pieces.push(id+': '+(state.answers[id]===undefined?'not answered':state.answers[id]===q.correct?'correct':'review needed'));const blob=new Blob([pieces.join('\n\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='session-04-my-worksheet.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function glossaryHTML(query=''){return glossary.filter(x=>x.join(' ').toLowerCase().includes(query.toLowerCase())).map(([w,m])=>'<div class="glossary-item"><b>'+esc(w)+'</b><p>'+esc(m)+'</p></div>').join('')||'<p>No matching term.</p>';}
function timerText(){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function updateTimer(){const v=document.getElementById('timerValue'),b=document.getElementById('timerToggle');if(v)v.textContent=timerText();if(b)b.textContent=timerRunning?'Pause':'Start';}
function openDrawer(type){lastFocus=document.activeElement;document.getElementById('drawer').hidden=false;const title=document.getElementById('drawerTitle'),body=document.getElementById('drawerBody');if(type==='outline'){title.textContent='Session contents';body.innerHTML='<div class="panel stack"><div class="row between"><h3>Class timer</h3><b id="timerValue">'+timerText()+'</b></div><div class="row"><button id="timerToggle">'+(timerRunning?'Pause':'Start')+'</button><button id="timerReset">Reset 120 min</button></div></div>'+slides.map((s,i)=>'<button class="outline-button '+(i===state.slide?'current':'')+'" data-outline-go="'+i+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(s.title)+'</button>').join('');}else if(type==='sources'){title.textContent='Sources and coverage';body.innerHTML='<p>Official Aptech class 4 covers Book Sessions 5 and 6: knowledge representation and types, knowledge/intelligence, the knowledge cycle, planning and decisions, reasoning types, propositional/predicate logic, performance analysis and metrics, and emerging/generative AI.</p><p>The supplied source is the April 2026 presenter’s outline. These explanations, examples, labs, and assignments supplement that outline. The full textbook and official question banks were not supplied.</p><a class="source-link04" href="https://aima.cs.berkeley.edu/" target="_blank" rel="noopener">Artificial Intelligence: A Modern Approach · knowledge and reasoning reference</a><a class="source-link04" href="https://scikit-learn.org/stable/modules/model_evaluation.html" target="_blank" rel="noopener">scikit-learn · model evaluation and metric definitions</a><a class="source-link04" href="https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-generative-artificial-intelligence" target="_blank" rel="noopener">NIST · Generative AI Profile</a><p>Campus policies, message labels, and scores are fictional. Browser code uses a teaching subset. The grounding comparison is scripted and makes no model call. Metric calculations use the displayed fictional data.</p><p>Reference links support further teacher reading. Access to the offline activities does not require those sites.</p>';}else{title.textContent='Word bank';body.innerHTML='<label for="wordSearch" class="small">Find a term</label><input id="wordSearch" type="text" placeholder="Predicate, recall, grounding…"><div id="wordList">'+glossaryHTML()+'</div>';}document.getElementById('closeDrawer').focus();}
function closeDrawer(){document.getElementById('drawer').hidden=true;if(lastFocus?.isConnected)lastFocus.focus();}
stage.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go!==undefined)return go(b.dataset.go);if(b.dataset.quiz){const id=b.dataset.quiz,a=Number(b.dataset.choice),q=quizData[id];state.answers[id]=a;save();document.querySelectorAll('[data-quiz="'+id+'"]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.choice)===a));const f=document.getElementById('feedback-'+id);f.textContent=(a===q.correct?'Yes. ':'Review the reason. ')+q.why;f.classList.toggle('bad',a!==q.correct);}if(b.dataset.knowledgeType){state.knowledgeType=b.dataset.knowledgeType;save();document.querySelectorAll('[data-knowledge-type]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('knowledgeDetail').innerHTML=typeHTML();}if(b.dataset.representation){state.representation=b.dataset.representation;save();document.querySelectorAll('[data-representation]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('representationDetail').innerHTML=representationHTML();}if(b.dataset.relation){const explanations={Amina:'Amina is an individual entity. “Instance of Student” places this person in the Student concept.',Student:'Student is a concept or class. Amina is an instance. The class is not the same thing as one individual.',Lab2:'Lab 2 is an individual room. “Part of” connects the room to a larger physical whole.',Building:'Science building is a whole that contains Lab 2. Its properties do not all automatically transfer to every part.',Course:'Course is a concept. “May enrol in” describes a possible relation, not proof that a specific enrolment happened.'};document.getElementById('relationDetail').textContent=explanations[b.dataset.relation];}if(b.id==='ruleStep'){state.ruleStep=Math.min(3,state.ruleStep+1);save();updateRules();}if(b.id==='ruleRun'){state.ruleStep=3;save();updateRules();}if(b.id==='ruleReset'){state.ruleStep=0;save();updateRules();}if(b.id==='toggleP'||b.id==='toggleQ'){const key=b.id==='toggleP'?'p':'q';state[key]=!state[key];b.textContent=key.toUpperCase()+': '+truth(state[key]);b.setAttribute('aria-pressed',state[key]);save();updateLogic();}if(b.dataset.person){state.people[b.dataset.person]=!state.people[b.dataset.person];save();render();}if(b.id==='runCode'){state.code=document.getElementById('codeEditor').value;state.codeOutput=runTeachingCode(state.code);save();document.getElementById('codeOutput').textContent=state.codeOutput;}if(b.id==='restoreCode'){state.code=INITIAL_CODE;state.codeOutput='';save();render();}if(b.dataset.codeLine!==undefined){const i=Number(b.dataset.codeLine);document.querySelectorAll('[data-code-line]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('lineDetail').innerHTML='<h3>Line '+(i+1)+'</h3><pre class="line04">'+esc(codeLines[i][0])+'</pre><p>'+codeLines[i][1]+'</p>';}if(b.dataset.threshold){state.threshold=Number(b.dataset.threshold);state.baseline=false;save();document.getElementById('threshold').value=state.threshold;document.getElementById('messageDetail').textContent='Select a message to explain its result.';updateMetrics();}if(b.id==='baselineBtn'){state.baseline=!state.baseline;save();document.getElementById('messageDetail').textContent='Select a message to explain its result.';updateMetrics();}if(b.dataset.message){const m=messages.find(m=>m.id===b.dataset.message),c=messageCategory(m);document.getElementById('messageDetail').textContent=m.id+': actual '+(m.spam?'spam':'normal')+', predicted '+(['tp','fp'].includes(c)?'spam':'normal')+'. '+({tp:'Correctly caught spam.',fp:'A normal message was wrongly flagged.',fn:'Spam was missed.',tn:'A normal message was correctly kept.'}[c]);}if(b.id==='generateDemo')showGenerated();if(b.id==='downloadWork'||b.id==='downloadFinal')downloadWork();if(b.id==='sourcesBtn')openDrawer('sources');});
stage.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){state.worksheet[t.dataset.field]=t.value;save();}if(t.id==='codeEditor'){state.code=t.value;save();}if(t.id==='threshold'){state.threshold=Number(t.value);state.baseline=false;save();document.getElementById('messageDetail').textContent='Select a message to explain its result.';updateMetrics();}});
stage.addEventListener('change',e=>{const t=e.target;if(t.dataset.fact){state.facts[t.dataset.fact]=t.value==='unknown'?null:t.value==='true';state.ruleStep=0;save();updateRules();}if(t.id==='logicOperator'){state.operator=t.value;save();updateLogic();}if(t.id==='genQuestion'||t.id==='grounded'){if(t.id==='genQuestion')state.genQuestion=t.value;else state.grounded=t.checked;state.genOutput='';save();document.getElementById('genAnswer').textContent='Predict the evidence-supported answer, then show it.';document.getElementById('genAnswer').classList.remove('unsupported');document.getElementById('genWhy').textContent='';}});
document.getElementById('prevBtn').onclick=()=>go(state.slide-1);document.getElementById('nextBtn').onclick=()=>go(state.slide+1);document.getElementById('outlineBtn').onclick=()=>openDrawer('outline');document.getElementById('glossaryBtn').onclick=()=>openDrawer('glossary');document.getElementById('closeDrawer').onclick=closeDrawer;document.getElementById('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){document.getElementById('fullscreenBtn').textContent='Use browser full screen';}};
document.getElementById('drawer').addEventListener('click',e=>{if(e.target.id==='drawer')closeDrawer();const b=e.target.closest('button');if(!b)return;if(b.dataset.outlineGo!==undefined){closeDrawer();go(b.dataset.outlineGo);}if(b.id==='timerToggle'){timerRunning=!timerRunning;if(timerRunning)timerInterval=setInterval(()=>{if(seconds>0)seconds--;else{timerRunning=false;clearInterval(timerInterval);}updateTimer();},1000);else clearInterval(timerInterval);updateTimer();}if(b.id==='timerReset'){seconds=7200;timerRunning=false;clearInterval(timerInterval);updateTimer();}});
document.getElementById('drawer').addEventListener('input',e=>{if(e.target.id==='wordSearch')document.getElementById('wordList').innerHTML=glossaryHTML(e.target.value);});
document.addEventListener('keydown',e=>{const drawer=document.getElementById('drawer');if(e.key==='Escape'&&!drawer.hidden){closeDrawer();return;}if(!drawer.hidden){if(e.key==='Tab'){const all=[...drawer.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowRight'){e.preventDefault();go(state.slide+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.slide-1);}if(e.key==='Home'){e.preventDefault();go(0);}if(e.key==='End'){e.preventDefault();go(slides.length-1);}});
state.slide=Math.max(0,Math.min(slides.length-1,Number(state.slide)||0));render();
